html:
{% set company = frappe.db.get_default("company") or frappe.db.get_single_value("Global Defaults", "default_company") %}
{% set company_logo = frappe.db.get_value("Company", company, "company_logo") if company else "" %}

<style>
  @page {
    size: A4;
    margin: 8mm;
  }

  body {
    margin: 0;
    padding: 0;
    font-family: Arial, sans-serif;
    color: #000;
  }

  .dn-page {
    width: 100%;
    min-height: 277mm;
    box-sizing: border-box;
    font-family: Arial, sans-serif;
    color: #000;
    font-size: 12px;
  }

  .dn-title {
    text-align: center;
    font-size: 19px;
    font-weight: 700;
    line-height: 1;
    margin: 0 0 3px 0;
    text-transform: uppercase;
  }

  .dn-main {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border: 1px solid #000;
  }

  .dn-main td,
  .dn-main th {
    border: 1px solid #000;
    vertical-align: top;
  }

  .company-block { padding: 6px 7px 4px 7px; }

  .company-logo-row { margin-bottom: 4px; } .company-logo-row img { width: 130px; height: 110px; object-fit: contain; display: block; }

  .company-name {
    font-size: 14px;
    font-weight: 700;
    line-height: 1.15;
    margin-bottom: 4px;
    text-transform: uppercase;
  }

  .company-line {
    font-size: 12px;
    line-height: 1.25;
  }

  .doc-info {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .doc-info td {
    border-left: none;
    border-right: none;
    border-top: none;
    border-bottom: 1px solid #000;
    padding: 3px 5px;
    height: 26px;
    font-size: 12px;
    line-height: 1.15;
  }

  .doc-info tr:last-child td {
    border-bottom: none;
  }

  .doc-info .info-label {
    width: 45%;
  }

  .doc-info .info-value {
    font-weight: 700;
  }

  .party-cell {
    height: 100px;
    padding: 5px 6px;
  }

  .party-title {
    font-size: 12px;
    margin-bottom: 4px;
  }

  .party-name {
    font-size: 14px;
    font-weight: 700;
    line-height: 1.25;
  }

  .party-text {
    font-size: 12px;
    line-height: 1.35;
  }

  .transport-info {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .transport-info td {
    border-left: none;
    border-right: none;
    border-top: none;
    border-bottom: 1px solid #000;
    padding: 4px 5px;
    height: 28px;
    font-size: 12px;
    line-height: 1.15;
  }

  .transport-info tr:last-child td {
    border-bottom: none;
  }

  .transport-info .info-label {
    width: 45%;
  }

  .goods-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .goods-table th,
  .goods-table td {
    border: 1px solid #000;
    padding: 4px 5px;
    font-size: 12px;
    line-height: 1.25;
  }

  .goods-table th {
    text-align: center;
    font-weight: 400;
  }

  .goods-table .goods-body td {
    height: 40px;
  }

  .center {
    text-align: center;
  }

  .right {
    text-align: right;
  }

  .bold {
    font-weight: 700;
  }

  .product-name {
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
  }

  .sub-product {
    display: block;
    margin-top: 5px;
    font-style: italic;
    font-size: 12px;
    font-weight: 400;
  }

  .vat-text {
    margin-top: 32px;
    text-align: right;
    font-size: 14px;
    font-weight: 700;
    font-style: italic;
  }

  .total-row td {
    height: 18px;
    padding-top: 2px;
    padding-bottom: 2px;
  }

  .bottom-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    border-left: 1px solid #000;
    border-right: 1px solid #000;
    border-bottom: 1px solid #000;
  }

  .bottom-table td {
    border: 1px solid #000;
    padding: 6px 6px;
    height: 48px;
    vertical-align: top;
    font-size: 12px;
  }

  .sign-cell {
    text-align: right;
  }

  .sign-company {
    font-size: 12px;
    font-weight: 700;
    margin-bottom: 25px;
  }

  .sign-title {
    font-size: 11px;
  }

  .generated {
    text-align: center;
    font-size: 12px;
    margin-top: 8px;
  }

  .stamp-area {
    margin-top: 4px;
    margin-left: 85px;
    width: 100px;
    height: 100px;
  }

  .stamp-area img {
    width: 100px;
    height: 100px;
    object-fit: contain;
    opacity: 0.9;
  }

  @media print {
    .dn-page {
      page-break-after: avoid;
    }
  }
</style>

<div class="dn-page">

  <div class="dn-title">Delivery Note</div>

  <table class="dn-main">
    <tr>
      <td style="width:50%;" class="company-block" rowspan="2">
        <div class="company-logo-row">{% if company_logo %}<img src="{{ company_logo }}" alt="Company Logo" width="130" height="110">{% else %}<img src="/files/AP_Logo.webp" alt="Company Logo" width="130" height="110" onerror="this.style.display='none'">{% endif %}</div><div class="company-name">ASIA PETROCHEMICALS LLC OPC</div><div class="company-line">Plot # A 23 B, Al Jazeera Industrial Area</div><div class="company-line">TRN : {{ doc.company_trn or "100283348900003" }}</div><div class="company-line">Emirate : Ras Al-Khaimah</div><div class="company-line">E-Mail : info@asia-petrochem.com</div>
      </td>

      <td style="width:25%;">
        <table class="doc-info">
          <tr>
            <td>
              <div>Delivery Note No.</div>
              <div class="info-value">{{ doc.name }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Supplier's Ref.</div>
              <div class="info-value">{{ doc.supplier_ref or doc.security_draft_delivery_note or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Buyer’s Order No.</div>
              <div class="info-value">{{ doc.job_order or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Despatch Document No.</div>
              <div class="info-value">{{ doc.security_inspection or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Despatched through</div>
              <div class="info-value">{{ doc.vehicle or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Terms of Delivery</div>
              <div class="info-value">{{ doc.terms_of_delivery or "DELIVERED" }}</div>
            </td>
          </tr>
        </table>
      </td>

      <td style="width:25%;">
        <table class="doc-info">
          <tr>
            <td>
              <div>Dated</div>
              <div class="info-value">
                {{ frappe.utils.formatdate(doc.loading_date) if doc.loading_date else frappe.utils.formatdate(doc.creation) }}
              </div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Mode/Terms of Payment</div>
              <div class="info-value">{{ doc.payment_terms or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Other Reference(s)</div>
              <div class="info-value">{{ doc.other_reference or doc.security_draft_delivery_note or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Dated</div>
              <div class="info-value">
                {{ frappe.utils.formatdate(doc.job_order_date) if doc.job_order_date else "-" }}
              </div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Destination</div>
              <div class="info-value">{{ doc.destination or "-" }}</div>
            </td>
          </tr>
        </table>
      </td>
    </tr>

    <tr></tr>

    <tr>
      <td class="party-cell">
        <div class="party-title">Consignee</div>
        <div class="party-name">{{ doc.customer or "-" }}</div>
        <div class="party-text">
          {{ doc.consignee_address or doc.customer_address or "" }}
        </div>

        <br>

        <div class="party-title">Buyer</div>
        <div class="party-name">{{ doc.buyer or doc.customer or "-" }}</div>
        <div class="party-text">
          {{ doc.buyer_address or doc.consignee_address or doc.customer_address or "" }}
        </div>

        {% if doc.emirate or doc.country or doc.trn or doc.place_of_supply %}
          <div class="party-text">
            {% if doc.emirate %}Emirate&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.emirate }}<br>{% endif %}
            {% if doc.country %}Country&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.country }}<br>{% endif %}
            {% if doc.trn %}TRN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;: {{ doc.trn }}<br>{% endif %}
            {% if doc.place_of_supply %}Place of supply&nbsp;: {{ doc.place_of_supply }}{% endif %}
          </div>
        {% endif %}
      </td>

      <td colspan="2">
        <table class="transport-info">
          <tr>
            <td>
              <div>Vehicle</div>
              <div class="info-value">{{ doc.vehicle or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Driver</div>
              <div class="info-value">{{ doc.driver or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Container Number</div>
              <div class="info-value">{{ doc.container_number or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Seal Number</div>
              <div class="info-value">{{ doc.seal_number or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>Loading Time</div>
              <div class="info-value">{{ doc.loading_time or "-" }}</div>
            </td>
          </tr>
          <tr>
            <td>
              <div>QC Status</div>
              <div class="info-value">{{ doc.qc_status or "-" }}</div>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <table class="goods-table">
    <thead>
      <tr>
        <th style="width:5%;">Sl<br>No.</th>
        <th style="width:11%;">Marks & Nos./<br>Container No.</th>
        <th style="width:11%;">No. & Kind<br>of Pkgs.</th>
        <th style="width:62%;">Description of Goods</th>
        <th style="width:11%;">Quantity</th>
      </tr>
    </thead>

    <tbody>
      <tr class="goods-body">
        <td class="center">1</td>

        <td class="center">
          {{ doc.container_number or "-" }}
        </td>

        <td class="center">
          {{ doc.package_type or doc.no_and_kind_of_packages or "-" }}
        </td>

        <td>
          <div class="product-name">{{ doc.material_description or doc.product_name or "-" }}</div>

          {% if doc.vehicle_type or doc.container_type %}
            <span class="sub-product">{{ doc.vehicle_type or doc.container_type }}</span>
          {% endif %}

          {% if doc.vat_text %}
            <div class="vat-text">{{ doc.vat_text }}</div>
          {% else %}
            <div class="vat-text">VAT 5%</div>
          {% endif %}

          {% for row in (doc.batch_allocations or []) %}
            <br>
            <div>
              <b>{{ row.product_name or row.product or "Batch Allocation" }}</b>
              {% if row.batch_number or row.batch %}
                <br>Batch: {{ row.batch_number or row.batch }}
              {% endif %}
              {% if row.coa_number or row.coa %}
                <br>COA: {{ row.coa_number or row.coa }}
              {% endif %}
            </div>
          {% endfor %}
        </td>

        <td class="center bold">
          {{ doc.quantity or "-" }} {{ doc.uom or "" }}
        </td>
      </tr>

      <tr class="total-row">
        <td></td>
        <td></td>
        <td></td>
        <td class="right">Total</td>
        <td class="center bold">{{ doc.quantity or "-" }} {{ doc.uom or "" }}</td>
      </tr>

      <tr class="total-row">
        <td></td>
        <td></td>
        <td></td>
        <td class="right">E. &amp; O.E</td>
        <td></td>
      </tr>
    </tbody>
  </table>

  <table class="bottom-table">
    <tr>
      <td style="width:50%;">
        Recd. in Good Condition
      </td>

      <td style="width:50%;" class="sign-cell">
        <div class="sign-company">for ASIA PETROCHEMICALS LLC OPC</div>
        <div class="sign-title">Authorised Signatory</div>
      </td>
    </tr>
  </table>

  <div class="generated">This is a Computer Generated Document</div>

  <div class="stamp-area">
    {% if company_logo %}
      <img src="{{ company_logo }}" alt="Company Stamp">
    {% else %}
      <img src="/files/AP_Logo.webp" alt="Company Stamp" onerror="this.style.display='none'">
    {% endif %}
  </div>

</div>
